    let currentFilter = 'home';
    let currentSearchTerm = '';
    let ordersList = [];
    let savedBills = [];

    const MOBILE_TERMS = {
      'New Mobile': [
        '1. New mobile is sold with the package and accessories selected on this bill.',
        '2. Customer must verify model, IMEI, accessories and device condition before accepting delivery.',
        '3. Manufacturer warranty, if applicable, is subject to the manufacturer warranty terms.',
        '4. Physical or liquid damage is not covered unless specifically covered by the applicable warranty.'
      ].join('\n'),
      'Keypad Mobile': [
        '1. Keypad mobile is sold with the package and accessories selected on this bill.',
        '2. Customer must verify model, IMEI, accessories and device condition before accepting delivery.',
        '3. Manufacturer/service warranty, if applicable, is subject to the stated warranty terms.',
        '4. Physical or liquid damage is not covered unless specifically covered by the applicable warranty.'
      ].join('\n'),
      'Used Mobile': [
        '1. Used mobile is sold in the condition inspected and accepted by the customer at the time of delivery.',
        '2. Customer is advised to verify display, touch, camera, speaker, microphone, charging, network, IMEI and accessories before accepting delivery.',
        '3. Return or exchange is not applicable after delivery unless specifically agreed by the shop in writing.',
        '4. Any warranty for a used mobile applies only if it is specifically stated on this bill.'
      ].join('\n')
    };

    function getMobileTerms(type) {
      return MOBILE_TERMS[type] || MOBILE_TERMS['New Mobile'];
    }

    function selectMobileType(type) {
      currentMobileType = ['New Mobile','Used Mobile','Keypad Mobile'].includes(type) ? type : 'New Mobile';
      document.querySelectorAll('.mobile-type-btn').forEach(btn => btn.classList.remove('active'));
      const id = currentMobileType === 'New Mobile' ? 'mobileTypeNew' : currentMobileType === 'Used Mobile' ? 'mobileTypeUsed' : 'mobileTypeKeypad';
      document.getElementById(id)?.classList.add('active');
      const typeEl = document.getElementById('pvMobileType');
      if (typeEl) typeEl.innerText = currentMobileType;
      const termsEl = document.getElementById('pvTerms');
      if (termsEl) termsEl.innerText = getMobileTerms(currentMobileType);
      const ramStorageGrid = document.getElementById('billRamStorageGrid');
      if (ramStorageGrid) ramStorageGrid.classList.toggle('sk-keypad-hidden', currentMobileType === 'Keypad Mobile');
      saveDraft();
      updateBillPreview();
    }

    /* ================================================================
       🔒 LOCKED BILL NUMBER FORMAT — DO NOT CHANGE THIS BLOCK.
       User-requested format:
       Invoice:     SK-DDMM-001
       Bill Details: SK-B-DDMM-001
       Keep internal `id` unchanged for Firebase/local sync compatibility.
       Do not change any other app functionality while modifying this.
       ================================================================ */
    const SK_BILL_NUMBER_FORMAT_LOCKED = true;
    const SK_BILL_PREFIX = 'SK';
    const SK_BILL_DETAILS_PREFIX = 'SK-B';

    function skBillDateKey(value) {
      const s = String(value || '').trim();
      let m = s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
      if (m) {
        const y = String(m[3]).length === 2 ? '20' + m[3] : m[3];
        return y + String(Number(m[2])).padStart(2, '0') + String(Number(m[1])).padStart(2, '0');
      }
      const d = new Date(value);
      if (!isNaN(d.getTime())) {
        return String(d.getFullYear()) + String(d.getMonth() + 1).padStart(2, '0') + String(d.getDate()).padStart(2, '0');
      }
      const now = new Date();
      return String(now.getFullYear()) + String(now.getMonth() + 1).padStart(2, '0') + String(now.getDate()).padStart(2, '0');
    }

    function skBillDDMM(value) {
      const key = skBillDateKey(value);
      return key.slice(6, 8) + key.slice(4, 6);
    }

    function skBillNumberFromDateSeq(dateValue, seq, details) {
      const prefix = details ? SK_BILL_DETAILS_PREFIX : SK_BILL_PREFIX;
      return `${prefix}-${skBillDDMM(dateValue)}-${String(Math.max(1, Number(seq) || 1)).padStart(3, '0')}`;
    }

    function skExistingBillSeq(bill) {
      // Accept both the previous CURRENT format and the locked current format
      // so old synced/local bills keep their sequence without changing internal IDs.
      const n = String(bill?.billNo || '').match(/^(?:SK(?:-B)?(?:-CURRENT)?)[\s-]+\d{4}-(\d{3})$/i);
      return n ? Number(n[1]) : 0;
    }

    function skIsCurrentBillNo(bill) {
      return /^SK(?:-B)?-\d{4}-\d{3}$/i.test(String(bill?.billNo || '').trim());
    }

    function skNextBillSequence(dateValue, list) {
      const dateKey = skBillDateKey(dateValue);
      const bills = Array.isArray(list) ? list : (typeof savedBills !== 'undefined' ? savedBills : []);
      let max = 0;
      bills.forEach(function(b) {
        if (skBillDateKey(b?.date) !== dateKey) return;
        max = Math.max(max, skExistingBillSeq(b));
      });
      // Legacy bills without the new billNo are also counted so numbering
      // does not reuse an already-existing daily number.
      const legacyCount = bills.filter(function(b) {
        return skBillDateKey(b?.date) === dateKey && !skExistingBillSeq(b);
      }).length;
      max = Math.max(max, legacyCount);
      return max + 1;
    }

    function skNextBillNo(dateValue) {
      return skBillNumberFromDateSeq(dateValue || new Date(), skNextBillSequence(dateValue || new Date(), savedBills), false);
    }

    function skEnsureBillNumbers(list) {
      if (!Array.isArray(list)) return false;
      let changed = false;
      const counters = {};
      // Reserve existing new-format numbers first.
      list.forEach(function(b) {
        const dateKey = skBillDateKey(b?.date);
        const seq = skExistingBillSeq(b);
        if (seq) counters[dateKey] = Math.max(counters[dateKey] || 0, seq);
      });
      // Normalize every stored invoice number to the locked SK-DDMM-001 format.
      // Old SK-CURRENT... values are converted without changing the internal id.
      list.forEach(function(b) {
        if (!b) return;
        const seq = skExistingBillSeq(b);
        if (seq) {
          const normalized = skBillNumberFromDateSeq(b.date, seq, false);
          if (b.billNo !== normalized) { b.billNo = normalized; changed = true; }
          return;
        }
        const dateKey = skBillDateKey(b.date);
        counters[dateKey] = (counters[dateKey] || 0) + 1;
        b.billNo = skBillNumberFromDateSeq(b.date, counters[dateKey], false);
        changed = true;
      });
      return changed;
    }


    window.addEventListener('DOMContentLoaded', () => {
      /* 🔒 SK V4.8 HOME-ONLY FIX:
         Home must render even if one optional startup/local-storage item is malformed.
         Do not change unrelated app functionality or data.
      */
      try { loadInitialData(); } catch (e) {
        console.error('SK Home startup data recovery:', e);
        if (!Array.isArray(inventory)) inventory = [];
        if (!Array.isArray(ordersList)) ordersList = [];
        if (!Array.isArray(savedBills)) savedBills = [];
      }

      // Apply the saved theme before the first Home render to avoid a light→dark repaint flash.
      try { setTheme(localStorage.getItem('sk_theme') || 'light', true); skInitThemeSettingsUI(); skInitUIAppearanceStudio(); } catch (e) { console.error('SK theme startup:', e); }

      // Render Home before optional UI restoration so the page cannot remain blank.
      try { renderCards(); } catch (e) {
        console.error('SK Home render error:', e);
      }

      try { applyShopConfig(); } catch (e) { console.error('SK shop config startup:', e); }
      try { applySavedLogo(); } catch (e) { console.error('SK logo startup:', e); }
      try { restoreDraft(); } catch (e) { console.error('SK draft startup:', e); }
      try { loadRepairSparesNote(); loadToolsOthersNote(); } catch (e) { console.error('SK spares note startup:', e); }
      try { updateOrderBadge(); } catch (e) { console.error('SK order badge startup:', e); }
      try { updateBillHistoryCount(); } catch (e) { console.error('SK bill count startup:', e); }
      try { skInitDmyDateInputs(document); } catch (e) { console.error('SK date input startup:', e); }

    });

    function loadInitialData() {
      const storedInv = localStorage.getItem('sk_inventory');
      if (storedInv) {
        try {
          const parsedInv = JSON.parse(storedInv);
          inventory = Array.isArray(parsedInv) ? parsedInv : [];
        } catch (e) {
          console.error('SK inventory data recovery:', e);
          inventory = [];
        }
      } else {
        inventory = JSON.parse(JSON.stringify(MASTER_INVENTORY));
        saveInventory();
      }

      const storedOrders = localStorage.getItem('sk_orders');
      if (storedOrders) {
        try {
          const parsedOrders = JSON.parse(storedOrders);
          ordersList = Array.isArray(parsedOrders) ? parsedOrders : [];
        } catch (e) {
          console.error('SK orders data recovery:', e);
          ordersList = [];
        }
      }

      const storedBills = localStorage.getItem('sk_bills');
      if (storedBills) {
        try {
          let rawBills = JSON.parse(storedBills);
          if (!Array.isArray(rawBills)) rawBills = [];
          const seen = new Set();
          savedBills = rawBills.filter(b => {
            const key = `${b?.custName || ''}_${b?.phone || ''}_${b?.model || ''}_${b?.price || ''}`;
            if (seen.has(key)) return false;
            seen.add(key);
            return true;
          });
          skEnsureBillNumbers(savedBills);
          localStorage.setItem('sk_bills', JSON.stringify(savedBills));
        } catch (e) {
          console.error('SK bills data recovery:', e);
          savedBills = [];
        }
      } else {
        savedBills = [];
      }
    }


    function saveInventory() {
      window.inventory = inventory;
      localStorage.setItem('sk_inventory', JSON.stringify(inventory));
      if(typeof window.skAutoAddLowStockOrders==='function')setTimeout(window.skAutoAddLowStockOrders,0);
    }

    function saveOrders() {
      localStorage.setItem('sk_orders', JSON.stringify(ordersList));
      updateOrderBadge();
    }

    function handleInputClear(el) {
      el.value = '';
    }

    // Repair Tools & IC Spares — isolated implementation.
    function loadRepairSparesNote() {
      const input = document.getElementById('repairSparesNoteInput');
      if (!input) return;
      try { input.value = localStorage.getItem('sk_repair_tools_note') || ''; }
      catch (error) { console.warn('SK repair note load failed:', error); }
    }

    function getRepairSparesInput() {
      const studio = document.getElementById('skRjSparesNoteInput');
      const legacy = document.getElementById('repairSparesNoteInput');
      if (studio && document.getElementById('skRjSparesView')?.style.display !== 'none') return studio;
      return legacy || studio;
    }
    function loadRepairSparesNoteIntoStudio() {
      const value = (() => { try { return localStorage.getItem('sk_repair_tools_note') || ''; } catch(e) { return ''; } })();
      const studio = document.getElementById('skRjSparesNoteInput');
      const legacy = document.getElementById('repairSparesNoteInput');
      if (studio) studio.value=value;
      if (legacy) legacy.value=value;
    }

    function saveRepairSparesNote() {
      const input = getRepairSparesInput();
      if (!input) return;
      const note = String(input.value || '').trim();
      try {
        if (note) localStorage.setItem('sk_repair_tools_note', note);
        else localStorage.removeItem('sk_repair_tools_note');
      } catch (error) { console.warn('SK repair note save failed:', error); }
      const studio = document.getElementById('skRjSparesNoteInput');
      const legacy = document.getElementById('repairSparesNoteInput');
      if(studio) studio.value=note;
      if(legacy) legacy.value=note;
      showToast(note ? 'Repair notes saved!' : 'Repair notes cleared!');
    }

    function shareRepairNotesWhatsApp() {
      const input = getRepairSparesInput();
      const note = String(input?.value || '').trim();
      if (!note) { showToast('Please enter a repair tools / IC spares list.'); input?.focus(); return; }
      const message = `SK MOBILES - Repair Tools & IC Spares Required\n\n${note}`;
      window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank', 'noopener,noreferrer');
    }

    // Tools & Others — separate monthly / rare-order manual note.
    function loadToolsOthersNote() {
      const input = document.getElementById('toolsOthersNoteInput');
      if (!input) return;
      try { input.value = localStorage.getItem('sk_tools_others_order_note') || ''; }
      catch (error) { console.warn('SK tools & others note load failed:', error); }
    }

    function saveToolsOthersNote() {
      const input = document.getElementById('toolsOthersNoteInput');
      if (!input) return;
      const note = String(input.value || '').trim();
      try { localStorage.setItem('sk_tools_others_order_note', note); }
      catch (error) { console.warn('SK tools & others note save failed:', error); }
      showToast(note ? 'Tools & Others note saved!' : 'Tools & Others note cleared!');
    }

    function shareToolsOthersNoteWhatsApp() {
      const input = document.getElementById('toolsOthersNoteInput');
      const note = String(input?.value || '').trim();
      if (!note) { showToast('Please enter a Tools & Others order note.'); input?.focus(); return; }
      const message = `SK MOBILES - Tools & Others Order Note\n\n${note}`;
      window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank', 'noopener,noreferrer');
    }

    function handleBillingModalClose() {
      autoSaveCurrentFormSilently();
      toggleModal('billingModal', false);
    }

    function handleNewBillClick() {
      window.__skInvoiceExportBill=null;
      window.__skEditingBillId='';
      autoSaveCurrentFormSilently();
      document.getElementById('usedMobileBillingForm').reset();
      const saveBtn=document.querySelector('.bill-action-save'); if(saveBtn){const sp=saveBtn.querySelector('span:last-child');if(sp)sp.textContent='Save Bill';}
      document.getElementById('billAdvance').value = "0";
      document.getElementById('billEmiMonths').value = "3";
      document.getElementById('billEmiInterest').value = "0";
      selectMobileType('New Mobile');
      selectPayMode('Cash');
      clearDraft();
      updateBillPreview();
      switchBillTab('new');
      showToast("New bill opened!");
    }

    function autoSaveCurrentFormSilently() {
      const custName = document.getElementById('billCustName').value.trim();
      const model = document.getElementById('billModel').value.trim();
      const price = parseFloat(document.getElementById('billTotalPrice').value) || 0;
      if (custName && model && price > 0) {
        const billDate = `${String(new Date().getDate()).padStart(2,'0')}/${String(new Date().getMonth()+1).padStart(2,'0')}/${new Date().getFullYear()}`;
        const newEntry = {
          id: `SK-B-${Date.now().toString().slice(-6)}`,
          billNo: skNextBillNo(billDate), date: billDate, mobileType: currentMobileType, custName,
          phone: document.getElementById('billCustPhone').value || '9876543210',
          address: document.getElementById('billCustAddress').value || '',
          brand: document.getElementById('billBrand').value || '', model,
          ram: document.getElementById('billRam').value || '', storage: document.getElementById('billStorage').value || '',
          color: document.getElementById('billColor').value || '', imei1: document.getElementById('billImei1').value || '',
          imei2: document.getElementById('billImei2').value || '', package: document.getElementById('billPackage').value || '',
          payMode: currentPayMode, price,
          advance: parseFloat(document.getElementById('billAdvance').value) || 0,
          balance: parseFloat((document.getElementById('billBalanceDisplay')?.innerText || '').replace(/\D/g,'')) || 0,
          emiMonths: parseInt(document.getElementById('billEmiMonths').value,10) || 0,
          emiInterest: parseFloat(document.getElementById('billEmiInterest').value) || 0,
          emiStartDate: document.getElementById('billEmiStartDate').value || '', creditDueDate: document.getElementById('billCreditDate').value || '',
          monthlyEmi: parseFloat(document.getElementById('billMonthlyEmi')?.value) || 0,
          emiHtml: currentPayMode === 'EMI' ? document.getElementById('pvEmiScheduleTbody').innerHTML : ''
        };
        const exists = savedBills.some(b => b.custName === newEntry.custName && b.model === newEntry.model && b.price === newEntry.price && b.phone === newEntry.phone);
        if (!exists) { savedBills.unshift(newEntry); localStorage.setItem('sk_bills', JSON.stringify(savedBills)); updateBillHistoryCount(); clearDraft(); }
      }
    }

    function saveShopCustomConfig() {
      const name = document.getElementById('cfgShopName').value.trim() || 'SK MOBILES';
      const addr = document.getElementById('cfgShopAddress').value.trim();
      const phone = document.getElementById('cfgShopPhone').value.trim();

      localStorage.setItem('sk_shop_name', name);
      localStorage.setItem('sk_shop_addr', addr);
      localStorage.setItem('sk_shop_phone', phone);

      applyShopConfig();
      showToast("Shop Profile updated!");
    }

    function saveCustomTerms() {
      const terms = document.getElementById('cfgTermsConditions').value;
      localStorage.setItem('sk_terms', terms);
      updateBillPreview();
      showToast("Terms updated!");
    }

    function resetDefaultTerms() {
      const defaultTerms = 
`1. Sold items are not returnable.
2. 7 Days Testing Warranty only.
3. No warranty for physical or liquid damage.
4. Customer has checked the IMEI and device condition before purchase.`;
      document.getElementById('cfgTermsConditions').value = defaultTerms;
      localStorage.setItem('sk_terms', defaultTerms);
      updateBillPreview();
      showToast("Reset to default terms!");
    }

    function applyShopConfig() {
      const name = localStorage.getItem('sk_shop_name') || 'SK MOBILES';
      const addr = localStorage.getItem('sk_shop_addr') || 'Shree Sai Complex, Salem Main Rd,\nOld Quarters Bus Stop, Old Quarters,\nDharmapuri, Tamil Nadu 636705 .';
      const phone = localStorage.getItem('sk_shop_phone') || '766 766 6362';

      document.getElementById('cfgShopName').value = name;
      document.getElementById('cfgShopAddress').value = addr;
      document.getElementById('cfgShopPhone').value = phone;

      document.getElementById('appHeaderTitle').innerText = name;
      document.getElementById('pvShopNameDisplay').innerText = name;
      document.getElementById('pvShopAddressDisplay').innerHTML = addr.replace(/\n/g, '<br>');
      document.getElementById('pvShopPhoneDisplay').innerText = phone;

      const threshold = localStorage.getItem('sk_low_threshold') || '3';
      document.getElementById('cfgLowStockThreshold').value = threshold;
      document.getElementById('pillLowStockVal').innerText = threshold;

      const terms = localStorage.getItem('sk_terms');
      if (terms) document.getElementById('cfgTermsConditions').value = terms;
    }

    function saveLowStockThreshold(val) {
      const v = Math.max(1, parseInt(val) || 3);
      localStorage.setItem('sk_low_threshold', v);
      document.getElementById('pillLowStockVal').innerText = v;
      renderCards();
      if(typeof window.skAutoAddLowStockOrders==='function')setTimeout(window.skAutoAddLowStockOrders,20);
      showToast("Low stock limit: " + v);
    }

    function uploadShopLogo(input) {
      if (input.files && input.files[0]) {
        const reader = new FileReader();
        reader.onload = function(e) {
          const logoData = e.target.result;
          localStorage.setItem('sk_custom_logo', logoData);
          applySavedLogo();
          showToast("Logo updated successfully!");
        };
        reader.readAsDataURL(input.files[0]);
      }
    }

    function resetShopLogo() {
      localStorage.removeItem('sk_custom_logo');
      applySavedLogo();
      showToast("Reset to default Logo.png!");
    }

    function applySavedLogo() {
      const savedLogo = localStorage.getItem('sk_custom_logo') || window.SK_MOBILES_EMBEDDED_LOGO || 'Logo.png';
      const headerLogo = document.getElementById('appHeaderLogo');
      const invoiceLogo = document.getElementById('invoiceLogoImg');
      const previewLogo = document.getElementById('settingsLogoPreview');

      if (headerLogo) headerLogo.src = savedLogo;
      if (invoiceLogo) invoiceLogo.src = savedLogo;
      if (previewLogo) previewLogo.src = savedLogo;
      const loginLogo = document.getElementById('skLoginLogoImg');
      if (loginLogo) {
        loginLogo.src = savedLogo;
        loginLogo.onerror = function(){ this.style.display='none'; const fb=this.nextElementSibling; if(fb) fb.style.display='flex'; };
      }
    }

    function bringModalToFront(modal) {
      if(!modal)return;
      const active=Array.from(document.querySelectorAll('.modal-overlay.active'));
      active.forEach((m,i)=>{m.style.setProperty('z-index',String(20000+i),'important');const sheet=m.querySelector('.modal-sheet');if(sheet)sheet.style.setProperty('z-index',String(20001+i),'important');});
      modal.style.setProperty('position','fixed','important'); modal.style.setProperty('inset','0','important'); modal.style.setProperty('z-index',String(22000+active.length),'important');
      const sheet=modal.querySelector('.modal-sheet'); if(sheet){sheet.style.setProperty('position','relative','important');sheet.style.setProperty('z-index',String(22001+active.length),'important');}
    }

    function toggleModal(modalId, show) {
      const modal=document.getElementById(modalId); if(!modal)return;
      if(show){
        modal.classList.add('active'); document.body.classList.add('modal-open');
        if(modalId==='orderModal')renderOrders(); if(modalId==='repairSparesModal')loadRepairSparesNote(); if(modalId==='toolsOthersNoteModal')loadToolsOthersNote();
        if(modalId==='billingModal'){switchBillTab('new');restoreDraft();updateBillPreview();}
        bringModalToFront(modal); requestAnimationFrame(()=>bringModalToFront(modal));
        if(typeof window.skAppHistoryModal==='function')window.skAppHistoryModal(modalId,true);
      }else{modal.classList.remove('active');document.body.classList.remove('modal-open');if(modalId==='viewBillModal'){const r=window.__skBillViewReturn||'';window.__skBillViewReturn='';if(r!=='creditLedger')toggleModal('billingModal',true);}if(typeof window.skAppHistoryModal==='function')window.skAppHistoryModal(modalId,false);}
    }

    function toggleLeftDrawer(show) {
      const drawer = document.getElementById('leftDrawer');
      if (drawer) {
        if (show) drawer.classList.add('active');
        else drawer.classList.remove('active');
        if(typeof window.skAppHistoryDrawer==='function')window.skAppHistoryDrawer(!!show);
      }
    }

    // Direct app-shell inventory navigation: close the current page/modal and switch
    // directly to the requested inventory category without changing any business logic.
    window.skGoToInventoryFilter = function(filter){
      try{
        document.querySelectorAll('.modal-overlay.active').forEach(function(m){
          m.classList.remove('active');
          m.style.display='';
        });
        document.body.classList.remove('modal-open');
        if(typeof window.toggleLeftDrawer==='function') window.toggleLeftDrawer(false);
        currentFilter = filter;
        if(typeof renderCards==='function') renderCards();
        window.scrollTo({top:0,behavior:'smooth'});
        if(typeof window.skAppHistoryFilter==='function') window.skAppHistoryFilter(filter);
      }catch(e){
        console.warn('Inventory navigation failed:',e);
      }
    };

    // Final app-shell Home action: close any open page/modal and return to Home.
    // This is navigation-only; it does not alter page data or business logic.
    window.skGoHomeFromAppShell = function(){
      try{
        document.querySelectorAll('.modal-overlay.active').forEach(function(m){
          m.classList.remove('active');
          m.style.display='';
        });
        document.body.classList.remove('modal-open');
        if(typeof window.toggleLeftDrawer==='function') window.toggleLeftDrawer(false);
        currentFilter='home';
        if(typeof renderCards==='function') renderCards();
        window.scrollTo({top:0,behavior:'smooth'});
        if(typeof window.skAppHistoryFilter==='function') window.skAppHistoryFilter('home');
      }catch(e){
        console.warn('Home navigation failed:',e);
      }
    };

    function showToast(msg) {
      const toast = document.getElementById('toast');
      toast.innerText = msg;
      toast.classList.add('show');
      setTimeout(() => { toast.classList.remove('show'); }, 2200);
    }

