    function skUpdateThemeChrome(theme){
      try{
        const meta=document.getElementById('skThemeColorMeta');
        if(meta) meta.setAttribute('content',SK_THEME_STATUS_COLORS[theme]||SK_THEME_STATUS_COLORS.light);
        document.documentElement.style.setProperty('--app-status-color',SK_THEME_STATUS_COLORS[theme]||SK_THEME_STATUS_COLORS.light);
      }catch(e){}
    }
    function skEnsureGoogleFont(fontKey){
      const families={
        inter:'Inter:wght@400;500;600;700;800',poppins:'Poppins:wght@400;500;600;700;800',
        nunito:'Nunito:wght@400;500;600;700;800',rubik:'Rubik:wght@400;500;600;700;800',
        manrope:'Manrope:wght@400;500;600;700;800',dm:'DM+Sans:wght@400;500;600;700;800',
        space:'Space+Grotesk:wght@400;500;600;700',lato:'Lato:wght@400;700;900',
        outfit:'Outfit:wght@400;500;600;700;800',roboto:'Roboto:wght@400;500;700;900',
        montserrat:'Montserrat:wght@400;500;600;700;800',opensans:'Open+Sans:wght@400;500;600;700;800',
        raleway:'Raleway:wght@400;500;600;700;800',quicksand:'Quicksand:wght@400;500;600;700',
        fira:'Fira+Sans:wght@400;500;600;700;800',work:'Work+Sans:wght@400;500;600;700;800',
        lexend:'Lexend:wght@400;500;600;700;800',sora:'Sora:wght@400;500;600;700;800',
        urbanist:'Urbanist:wght@400;500;600;700;800',barlow:'Barlow:wght@400;500;600;700;800',
        archivo:'Archivo:wght@400;500;600;700;800',mulish:'Mulish:wght@400;500;600;700;800',
        karla:'Karla:wght@400;500;600;700;800',cabin:'Cabin:wght@400;500;600;700',
        source:'Source+Sans+3:wght@400;500;600;700;800',ibmplex:'IBM+Plex+Sans:wght@400;500;600;700',
        josefin:'Josefin+Sans:wght@400;500;600;700',playfair:'Playfair+Display:wght@400;500;600;700;800'
      };
      const spec=families[fontKey]; if(!spec)return;
      const id='sk-font-google-'+fontKey;
      if(document.getElementById(id))return;
      const link=document.createElement('link');link.id=id;link.rel='stylesheet';
      link.href='https://fonts.googleapis.com/css2?family='+spec+'&display=swap';
      document.head.appendChild(link);
    }

    function setAppFont(fontKey, silent){
      if(!SK_APP_FONTS[fontKey]) fontKey='jakarta';
      const family=SK_APP_FONTS[fontKey];
      skEnsureGoogleFont(fontKey);
      const labelMap={
        jakarta:'Plus Jakarta Sans',inter:'Inter',poppins:'Poppins',nunito:'Nunito',rubik:'Rubik',
        manrope:'Manrope',dm:'DM Sans',space:'Space Grotesk',lato:'Lato',outfit:'Outfit',
        roboto:'Roboto',montserrat:'Montserrat',opensans:'Open Sans',raleway:'Raleway',quicksand:'Quicksand',
        fira:'Fira Sans',work:'Work Sans',lexend:'Lexend',sora:'Sora',urbanist:'Urbanist',
        barlow:'Barlow',archivo:'Archivo',mulish:'Mulish',karla:'Karla',cabin:'Cabin',
        source:'Source Sans 3',ibmplex:'IBM Plex Sans',josefin:'Josefin Sans',playfair:'Playfair Display',
        serif:'Classic Serif',mono:'Clean Mono'
      };
      document.documentElement.setAttribute('data-font-family',fontKey);
      document.documentElement.style.setProperty('--app-font',family);
      localStorage.setItem('sk_font_family',fontKey);

      /* Force the selected family onto the rendered app, including elements
         that previously had their own fixed font-family declaration. */
      try{
        document.body.style.setProperty('font-family',family,'important');
        const viewport=document.querySelector('.app-viewport');
        if(viewport) viewport.style.setProperty('font-family',family,'important');
      }catch(e){}

      const sel=document.getElementById('skFontFamilySelect');
      if(sel) sel.value=fontKey;

      const preview=document.getElementById('skFontPreview');
      if(preview){
        preview.style.setProperty('font-family',family,'important');
        preview.innerHTML='<strong>'+labelMap[fontKey]+'</strong><span>SK MOBILES — Sample Text 12345</span><small>Regular • Medium • Bold</small>';
      }

      /* Update the selectable font cards immediately so the chosen typeface
         is visible before the user closes the picker. */
      document.querySelectorAll('.sk-font-choice').forEach(function(card){
        const key=card.getAttribute('data-font-key');
        card.classList.toggle('active',key===fontKey);
        if(SK_APP_FONTS[key]) card.style.setProperty('font-family',SK_APP_FONTS[key],'important');
      });

      /* Ask the browser to load the requested web font, then re-apply the
         family so a cached/fallback face cannot remain visually stuck. */
      try{
        if(document.fonts && document.fonts.load){
          const familyName = family.split(',')[0].trim().replace(/^['\"]|['\"]$/g,'');
          document.fonts.load('400 16px "'+familyName+'"').then(function(){
            document.documentElement.style.setProperty('--app-font',family);
            document.documentElement.setAttribute('data-font-family',fontKey);
            document.body.style.setProperty('font-family',family);
            if(viewport) viewport.style.setProperty('font-family',family);
            if(preview) preview.style.setProperty('font-family',family);
          }).catch(function(){});
        }
      }catch(e){}

      if(!silent && typeof showToast==='function') showToast('Font applied: '+(labelMap[fontKey]||fontKey));
    }
    window.setAppFont=setAppFont;
    function openAppFontPicker(){
      const modal=document.getElementById('skFontPickerModal');
      if(!modal) return;
      renderAppFontPicker();
      toggleModal('skFontPickerModal', true);
    }
    window.openAppFontPicker=openAppFontPicker;
    function renderAppFontPicker(){
      const grid=document.getElementById('skFontPickerGrid');
      if(!grid) return;
      const labels={
        jakarta:'Plus Jakarta Sans',inter:'Inter',poppins:'Poppins',nunito:'Nunito',rubik:'Rubik',
        manrope:'Manrope',dm:'DM Sans',space:'Space Grotesk',lato:'Lato',outfit:'Outfit',
        roboto:'Roboto',montserrat:'Montserrat',opensans:'Open Sans',raleway:'Raleway',quicksand:'Quicksand',
        fira:'Fira Sans',work:'Work Sans',lexend:'Lexend',sora:'Sora',urbanist:'Urbanist',
        barlow:'Barlow',archivo:'Archivo',mulish:'Mulish',karla:'Karla',cabin:'Cabin',
        source:'Source Sans 3',ibmplex:'IBM Plex Sans',josefin:'Josefin Sans',playfair:'Playfair Display',
        serif:'Classic Serif',mono:'Clean Mono'
      };
      const current=localStorage.getItem('sk_font_family')||'jakarta';
      grid.innerHTML=Object.keys(labels).map(k=>`<button type="button" class="sk-font-choice${k===current?' active':''}" data-font-key="${k}" onclick="selectAppFontCard('${k}',this)"><span>${labels[k]}</span><small>SK MOBILES • 12345</small></button>`).join('');
      grid.querySelectorAll('.sk-font-choice').forEach(function(card){
        const key=card.getAttribute('data-font-key');
        if(SK_APP_FONTS[key]) card.style.setProperty('font-family',SK_APP_FONTS[key],'important');
      });
    }
    function selectAppFontCard(fontKey, el){
      setAppFont(fontKey, false);
      document.querySelectorAll('.sk-font-choice').forEach(x=>x.classList.remove('active'));
      if(el) el.classList.add('active');
    }
    window.selectAppFontCard=selectAppFontCard;
    function toggleThemeIconPanel(){
      const body=document.getElementById('skThemeIconPanelBody'),btn=document.getElementById('skThemePanelToggle');
      if(!body)return;
      const collapsed=body.getAttribute('data-collapsed')==='1';
      body.setAttribute('data-collapsed',collapsed?'0':'1');
      if(btn){btn.setAttribute('aria-expanded',collapsed?'true':'false');btn.textContent=collapsed?'⌃ Minimise':'⌄ Expand';}
      localStorage.setItem('sk_theme_panel_collapsed',collapsed?'0':'1');
    }
    window.toggleThemeIconPanel=toggleThemeIconPanel;
    function skInitThemeSettingsUI(){
      try{
        const savedFont=localStorage.getItem('sk_font_family')||'jakarta'; setAppFont(savedFont,true);
        const body=document.getElementById('skThemeIconPanelBody'),btn=document.getElementById('skThemePanelToggle');
        if(body){const collapsed=localStorage.getItem('sk_theme_panel_collapsed')==='1';body.setAttribute('data-collapsed',collapsed?'1':'0');if(btn){btn.setAttribute('aria-expanded',collapsed?'false':'true');btn.textContent=collapsed?'⌄ Expand':'⌃ Minimise';}}
      }catch(e){}
    }

    /* ================================================================
       UI & APPEARANCE STUDIO — token engine
       All preferences are presentation-only and persisted under one key.
       ================================================================ */
    const SK_APPEARANCE_KEY = 'sk_appearance_settings';
    const SK_APPEARANCE_DEFAULTS = {
      preset:'classic', themeMode:'light', accent:'blue', customHex:'#2563EB',
      surface:'offwhite', cardRadius:'modern', buttonRadius:'modern', cardSurface:'blur',
      header:'glass', nav:'floating', scale:'normal', aura:true, haptic:true, sound:false, motion:false
    };
    const SK_APPEARANCE_ACCENTS = {
      blue:'#2563EB', violet:'#7C3AED', green:'#059669', rose:'#E11D48',
      amber:'#D97706', teal:'#0D9488', coral:'#F05A5A', indigo:'#4F46E5'
    };
    const SK_APPEARANCE_PRESETS = {
      classic:{theme:'light',accent:'blue',surface:'offwhite',cardSurface:'blur',header:'glass',nav:'fixed',cardRadius:'modern',buttonRadius:'modern',aura:true},
      liquid:{theme:'light',accent:'blue',surface:'accent',cardSurface:'ios',header:'glass',nav:'floating',cardRadius:'smooth',buttonRadius:'pill',aura:true},
      white:{theme:'light',accent:'blue',surface:'flat',cardSurface:'border',header:'minimal',nav:'fixed',cardRadius:'standard',buttonRadius:'modern',aura:false},
      midnight:{theme:'dark',accent:'violet',surface:'flat',cardSurface:'shadow',header:'minimal',nav:'floating',cardRadius:'modern',buttonRadius:'modern',aura:false},
      emerald:{theme:'light',accent:'green',surface:'accent',cardSurface:'ios',header:'glass',nav:'floating',cardRadius:'smooth',buttonRadius:'modern',aura:true},
      amber:{theme:'dark',accent:'amber',surface:'glow',cardSurface:'blur',header:'glass',nav:'floating',cardRadius:'modern',buttonRadius:'modern',aura:true},
      ruby:{theme:'light',accent:'rose',surface:'classic',cardSurface:'shadow',header:'solid',nav:'fixed',cardRadius:'standard',buttonRadius:'modern',aura:false},
      ocean:{theme:'light',accent:'teal',surface:'accent',cardSurface:'blur',header:'glass',nav:'floating',cardRadius:'smooth',buttonRadius:'modern',aura:true}
    };
    let skAppearanceSystemMedia = null;

    function skAppearanceRead(){
      try{
        const raw=localStorage.getItem(SK_APPEARANCE_KEY);
        if(!raw) return {...SK_APPEARANCE_DEFAULTS};
        const parsed=JSON.parse(raw);
        return {...SK_APPEARANCE_DEFAULTS,...(parsed&&typeof parsed==='object'?parsed:{})};
      }catch(e){ return {...SK_APPEARANCE_DEFAULTS}; }
    }
    function skAppearanceSave(settings){
      try{localStorage.setItem(SK_APPEARANCE_KEY,JSON.stringify(settings));}catch(e){}
    }
    function skHex(hex){
      const s=String(hex||'').trim().replace(/^#/,'');
      if(/^[0-9a-f]{3}$/i.test(s)) return '#'+s.split('').map(c=>c+c).join('').toUpperCase();
      if(/^[0-9a-f]{6}$/i.test(s)) return '#'+s.toUpperCase();
      return '#2563EB';
    }
    function skHexRgb(hex){
      const h=skHex(hex).slice(1);return {r:parseInt(h.slice(0,2),16),g:parseInt(h.slice(2,4),16),b:parseInt(h.slice(4,6),16)};
    }
    function skRgbHex(r,g,b){return '#'+[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('').toUpperCase();}
    function skMix(hex,target,amount){
      const a=skHexRgb(hex), b=skHexRgb(target), p=Math.max(0,Math.min(1,amount));
      return skRgbHex(a.r+(b.r-a.r)*p,a.g+(b.g-a.g)*p,a.b+(b.b-a.b)*p);
    }
    function skAppearanceResolvedMode(settings){
      if(settings.themeMode==='system') return window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';
      if(settings.themeMode==='scheduled'){
        const hour=new Date().getHours();
        return (hour>=18 || hour<6)?'dark':'light';
      }
      return settings.themeMode==='dark'?'dark':'light';
    }
    function skAppearanceThemeFor(settings){
      const mode=skAppearanceResolvedMode(settings);
      const map={
        classic:{light:'light',dark:'dark'}, liquid:{light:'apple-light',dark:'apple-dark'},
        white:{light:'apple-light',dark:'apple-dark'}, midnight:{light:'midnight',dark:'obsidian'},
        emerald:{light:'emerald',dark:'forest'}, amber:{light:'sunset',dark:'cyber'},
        ruby:{light:'rose',dark:'crimson'}, ocean:{light:'ocean',dark:'dark'}
      };
      return (map[settings.preset]||map.classic)[mode];
    }
    function skAppearanceApplyTokens(settings){
      const root=document.documentElement;
      const resolved=skAppearanceResolvedMode(settings);
      const preset=SK_APPEARANCE_PRESETS[settings.preset]||SK_APPEARANCE_PRESETS.classic;
      const accentName=settings.accent==='custom'?'custom':settings.accent;
      const accent=accentName==='custom'?skHex(settings.customHex):skHex(SK_APPEARANCE_ACCENTS[accentName]||SK_APPEARANCE_ACCENTS.blue);
      const light=resolved==='light';
      const primary2=skMix(accent,light?'#0F172A':'#FFFFFF',light?.12:.18);
      const border=light?skMix(accent,'#E2E8F0',.78):skMix(accent,'#FFFFFF',.82);
      const page=light?skMix(accent,'#F8FAFC',.93):'#070A10';
      const bg=light?skMix(accent,'#FFFFFF',.97):'#05070C';
      const card=light?'#FFFFFF':'#0D121C';
      const model=light?skMix(accent,'#F8FAFC',.94):'#0A0F18';
      const pill=light?skMix(accent,'#F1F5F9',.88):'rgba(255,255,255,.06)';
      const muted=light?'#64748B':'#94A3B8';
      const text=light?'#0F172A':'#F8FAFC';
      const shadow=light?`0 8px 24px ${skMix(accent,'#FFFFFF',.78)}55`:`0 10px 28px rgba(0,0,0,.30)`;
      root.style.setProperty('--primary',accent);
      root.style.setProperty('--primary-gradient',`linear-gradient(135deg,${accent} 0%,${primary2} 100%)`);
      root.style.setProperty('--glass-btn-bg',accent);
      root.style.setProperty('--glass-btn-border',primary2);
      root.style.setProperty('--glass-pill-active',accent);
      root.style.setProperty('--glass-pill-border',primary2);
      root.style.setProperty('--badge-bg',light?skMix(accent,'#FFFFFF',.90):skMix(accent,'#000000',.72));
      root.style.setProperty('--badge-border',light?skMix(accent,'#FFFFFF',.70):skMix(accent,'#FFFFFF',.65));
      root.style.setProperty('--card-border',border);
      root.style.setProperty('--page-bg',page);
      root.style.setProperty('--bg',bg);
      root.style.setProperty('--card-bg',card);
      root.style.setProperty('--model-bg',model);
      root.style.setProperty('--input-bg',light?'#FFFFFF':'#0B111B');
      root.style.setProperty('--pill-bg',pill);
      root.style.setProperty('--chip-bg',border);
      root.style.setProperty('--bottom-nav-bg',light?'rgba(255,255,255,.94)':'rgba(8,11,18,.94)');
      root.style.setProperty('--header-bg',light?'rgba(255,255,255,.90)':'rgba(7,10,16,.90)');
      root.style.setProperty('--modal-bg',light?'#FFFFFF':'#0B1019');
      root.style.setProperty('--text',text);
      root.style.setProperty('--text-muted',muted);
      root.style.setProperty('--glass-shadow',shadow);
      root.style.setProperty('--card-elevation',shadow);
      const cardRadiusMap={sharp:'0px',standard:'8px',modern:'12px',smooth:'16px',pill:'24px'};
      const buttonRadiusMap={sharp:'0px',modern:'8px',smooth:'14px',pill:'999px'};
      const scaleMap={compact:'.92',normal:'1',comfortable:'1.08'};
      root.style.setProperty('--ui-card-radius',cardRadiusMap[settings.cardRadius]||'12px');
      root.style.setProperty('--ui-button-radius',buttonRadiusMap[settings.buttonRadius]||'8px');
      root.style.setProperty('--ui-scale',scaleMap[settings.scale]||'1');
      root.style.setProperty('--ui-aura-opacity',settings.aura?.45:0);
      root.setAttribute('data-ui-mode',resolved);
      root.setAttribute('data-ui-preset',settings.preset);
      root.setAttribute('data-ui-accent',accentName);
      root.setAttribute('data-ui-header',settings.header);
      root.setAttribute('data-ui-nav',settings.nav);
      root.setAttribute('data-ui-scale',settings.scale);
      root.setAttribute('data-ui-aura',settings.aura?'on':'off');
      root.setAttribute('data-ui-haptic',settings.haptic?'on':'off');
      root.setAttribute('data-ui-sound',settings.sound?'on':'off');
      root.setAttribute('data-ui-motion',settings.motion?'on':'off');
      root.setAttribute('data-ui-surface',settings.surface);
      root.setAttribute('data-ui-card-radius',settings.cardRadius);
      root.setAttribute('data-ui-button-radius',settings.buttonRadius);
      root.setAttribute('data-ui-card-surface',settings.cardSurface);
      root.style.colorScheme=resolved;
      const hexEl=document.getElementById('skAppearanceHexValue');if(hexEl)hexEl.textContent=accent.toUpperCase();
      const colorEl=document.getElementById('skAppearanceCustomHex');if(colorEl && /^#[0-9A-F]{6}$/i.test(skHex(settings.customHex)))colorEl.value=skHex(settings.customHex);
      const preview=document.querySelector('#skUiAppearanceStudio .sk-ui-preview-card');if(preview)preview.style.setProperty('--preview-primary',accent);
    }
    function skAppearanceSyncControls(settings){
      const root=document.getElementById('skUiAppearanceStudio');if(!root)return;
      root.querySelectorAll('[data-setting-group]').forEach(group=>{
        const key=group.getAttribute('data-setting-group'), value=settings[key];
        group.querySelectorAll('[data-value]').forEach(btn=>btn.classList.toggle('active',String(btn.dataset.value)===String(value)));
      });
      const aura=document.getElementById('skUiAura'),h=document.getElementById('skUiHaptic'),snd=document.getElementById('skUiSound'),m=document.getElementById('skUiMotion');
      if(aura)aura.checked=!!settings.aura;if(h)h.checked=!!settings.haptic;if(snd)snd.checked=!!settings.sound;if(m)m.checked=!!settings.motion;
      root.querySelectorAll('.sk-ui-profile').forEach(btn=>btn.classList.toggle('active',btn.dataset.value===settings.preset));
    }
    function skAppearanceApply(settings,opts){
      const next={...SK_APPEARANCE_DEFAULTS,...settings};
      skAppearanceSave(next);skAppearanceApplyTokens(next);skAppearanceSyncControls(next);
      if(opts?.theme){
        window.__skAppearanceApplying=true;
        try{setTheme(skAppearanceThemeFor(next),true);}catch(e){}
        window.__skAppearanceApplying=false;
      }
      return next;
    }
    function skAppearanceSet(key,value){
      let settings=skAppearanceRead();
      if(key==='preset'){
        const p=SK_APPEARANCE_PRESETS[value]||SK_APPEARANCE_PRESETS.classic;
        settings={...settings,preset:value,accent:p.accent||settings.accent,themeMode:p.theme||settings.themeMode,surface:p.surface,cardSurface:p.cardSurface,header:p.header,nav:p.nav,cardRadius:p.cardRadius,buttonRadius:p.buttonRadius,aura:p.aura};
        if(value==='liquid'||value==='white') settings.themeMode='light';
        if(value==='midnight'||value==='amber') settings.themeMode='dark';
        if(value==='classic'||value==='emerald'||value==='ruby'||value==='ocean') settings.themeMode='light';
        skAppearanceApply(settings,{theme:true});
      }else{
        if(key==='accent') settings.accent=value;
        else if(key==='themeMode') settings.themeMode=value;
        else if(['aura','haptic','sound','motion'].includes(key)) settings[key]=!!value;
        else settings[key]=value;
        if(key==='accent' && value!=='custom') settings.customHex=skHex(SK_APPEARANCE_ACCENTS[value]||SK_APPEARANCE_ACCENTS.blue);
        skAppearanceApply(settings,{theme:key==='themeMode'});
      }
    }
    function skAppearanceSetCustomAccent(value){
      const hex=skHex(value),settings=skAppearanceRead();settings.accent='custom';settings.customHex=hex;settings.preset='classic';skAppearanceApply(settings,{theme:false});
    }
    function skResetAppearanceStudio(){
      const next={...SK_APPEARANCE_DEFAULTS};
      skAppearanceApply(next,{theme:true});
      try{localStorage.removeItem('sk_theme_depth');}catch(e){}
      const slider=document.getElementById('themeDepthSlider');if(slider)slider.value=100;
      const label=document.getElementById('depthValueLabel');if(label)label.textContent='100%';
      if(typeof showToast==='function')showToast('Appearance Studio reset to Classic Blue.');
    }
    function skInitUIAppearanceStudio(){
      let settings=skAppearanceRead();
      /* One-time migration from the older sk_ui_* bridge. */
      if(!localStorage.getItem(SK_APPEARANCE_KEY)){
        const oldMap={header:'header',nav:'nav',scale:'scale',aura:'aura',haptic:'haptic',motion:'motion',surface:'surface',cardRadius:'cardRadius',buttonRadius:'buttonRadius',cardSurface:'cardSurface'};
        Object.keys(oldMap).forEach(k=>{const raw=localStorage.getItem('sk_ui_'+oldMap[k]);if(raw!==null)settings[k]=raw==='true'?true:raw==='false'?false:raw;});
      }
      skAppearanceApply(settings,{theme:true});
      skInitUIAppearanceBehavior();
      skInitAppearanceSandbox();
      if(!skAppearanceSystemMedia && window.matchMedia){
        skAppearanceSystemMedia=window.matchMedia('(prefers-color-scheme: dark)');
        const onSystemChange=()=>{const s=skAppearanceRead();if(s.themeMode==='system')skAppearanceApply(s,{theme:false});};
        if(skAppearanceSystemMedia.addEventListener)skAppearanceSystemMedia.addEventListener('change',onSystemChange);else skAppearanceSystemMedia.addListener(onSystemChange);
      }
    }
    let skAppearanceClockTimer=null;
    let skAppearanceAudioContext=null;
    function skAppearanceSoftClick(){
      try{
        const AC=window.AudioContext||window.webkitAudioContext;
        if(!AC)return;
        skAppearanceAudioContext=skAppearanceAudioContext||new AC();
        const ctx=skAppearanceAudioContext;
        if(ctx.state==='suspended')ctx.resume().catch(()=>{});
        const osc=ctx.createOscillator(),gain=ctx.createGain();
        osc.type='sine'; osc.frequency.setValueAtTime(620,ctx.currentTime);
        osc.frequency.exponentialRampToValueAtTime(470,ctx.currentTime+0.045);
        gain.gain.setValueAtTime(0.0001,ctx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.035,ctx.currentTime+0.006);
        gain.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+0.055);
        osc.connect(gain);gain.connect(ctx.destination);osc.start();osc.stop(ctx.currentTime+0.06);
      }catch(e){}
    }
    function skAppearanceRefreshScheduled(){
      const s=skAppearanceRead();
      if(s.themeMode==='scheduled'){
        skAppearanceApply(s,{theme:true});
      }
    }
    function skInitUIAppearanceBehavior(){
      if(window.__skUiAppearanceBehaviorReady)return;
      window.__skUiAppearanceBehaviorReady=true;
      document.addEventListener('click',function(ev){
        const target=ev.target&&ev.target.closest?ev.target.closest('button,[role="button"],.nav-item,.tab,.mobile-type-btn,.billing-tab-btn'):null;
        if(!target)return;
        const s=skAppearanceRead();
        if(s.haptic && navigator.vibrate){try{navigator.vibrate([15]);}catch(e){}}
        if(s.sound)skAppearanceSoftClick();
      },{passive:true});
      if(skAppearanceClockTimer)clearInterval(skAppearanceClockTimer);
      skAppearanceClockTimer=setInterval(skAppearanceRefreshScheduled,60000);
      document.addEventListener('visibilitychange',function(){if(!document.hidden)skAppearanceRefreshScheduled();},{passive:true});
    }
    function skAppearanceSyncFromLegacyTheme(theme){
      if(window.__skAppearanceApplying)return;
      const map={light:'classic',ocean:'ocean',emerald:'emerald',rose:'ruby',midnight:'midnight',cyber:'amber','apple-light':'white','apple-dark':'midnight',royal:'classic',sunset:'amber',dark:'midnight'};
      const settings=skAppearanceRead();settings.preset=map[theme]||settings.preset;
      skAppearanceSave(settings);skAppearanceApplyTokens(settings);skAppearanceSyncControls(settings);
    }
    function skAppearanceSandboxSet(tab){
      const root=document.getElementById('skUiAppearanceStudio');
      if(!root)return;
      const allowed=['home','cards','inputs','navigation'];
      const next=allowed.includes(tab)?tab:'home';
      root.querySelectorAll('.sk-ui-sandbox-tab').forEach(btn=>{
        const active=btn.dataset.sandboxTab===next;
        btn.classList.toggle('active',active);
        btn.setAttribute('aria-selected',active?'true':'false');
      });
      root.querySelectorAll('.sk-ui-sandbox-pane').forEach(pane=>{
        const active=pane.dataset.sandboxPane===next;
        pane.classList.toggle('active',active);
        pane.hidden=!active;
      });
      skAppearanceSandboxRefresh();
      try{sessionStorage.setItem('sk_ui_sandbox_tab',next);}catch(e){}
    }
    function skAppearanceSandboxRefresh(){
      const root=document.getElementById('skUiAppearanceStudio');
      if(!root)return;
      const money=v=>'₹'+Number(v||0).toLocaleString('en-IN');
      try{
        const inv=Array.isArray(window.inventory)?window.inventory:[];
        const stock=inv.reduce((sum,item)=>sum+(Number(item?.stock)||0),0);
        const stockEl=document.getElementById('skSandboxStock'); if(stockEl)stockEl.textContent=String(stock);
      }catch(e){}
      try{
        const credit=typeof window.skOutstandingTotalForHome==='function'?Number(window.skOutstandingTotalForHome()||0):0;
        const el=document.getElementById('skSandboxCredit'); if(el)el.textContent=money(credit);
        const top=document.getElementById('skSandboxOutstanding'); if(top)top.textContent=money(credit);
      }catch(e){}
      try{
        const bills=JSON.parse(localStorage.getItem('sk_bills')||'[]');
        const el=document.getElementById('skSandboxBills'); if(el)el.textContent=String(Array.isArray(bills)?bills.length:0);
      }catch(e){}
      try{
        const jobs=JSON.parse(localStorage.getItem('skx_repair_jobs_v2')||'[]');
        const pending=Array.isArray(jobs)?jobs.filter(j=>['Received','Checking','Repairing'].includes(String(j?.status||''))).length:0;
        const el=document.getElementById('skSandboxJobs'); if(el)el.textContent=String(pending);
      }catch(e){}
    }
    function skAppearanceSandboxAction(action){
      try{
        const settings=document.getElementById('settingsModal');
        if(settings){settings.classList.remove('active');document.body.classList.remove('modal-open');}
        const go={
          home:()=>window.skGoHomeFromAppShell?.(),
          glass:()=>window.skGoToInventoryFilter?.('glass'),
          combo:()=>window.skGoToInventoryFilter?.('combo'),
          billing:()=>{window.toggleModal?.('billingModal',true);window.scrollTo?.({top:0,behavior:'smooth'});},
          orders:()=>{window.toggleModal?.('orderModal',true);window.scrollTo?.({top:0,behavior:'smooth'});},
          newbill:()=>{window.toggleModal?.('billingModal',true);window.handleNewBillClick?.();window.scrollTo?.({top:0,behavior:'smooth'});},
          customers:()=>window.openCustomers?.() || window.openCustomerModal?.() || window.skOpenCreditLedger?.(),
          stock:()=>window.skGoToInventoryFilter?.('all'),
          pending:()=>window.skOpenPendingRepairJobs?.(),
          credit:()=>window.skOpenCreditLedger?.(),
          bills:()=>{window.toggleModal?.('billingModal',true);window.switchBillTab?.('history');window.scrollTo?.({top:0,behavior:'smooth'});},
          billingFromInput:()=>{
            window.toggleModal?.('billingModal',true);
            window.handleNewBillClick?.();
            const name=document.getElementById('skSandboxCustomer')?.value||'';
            const phone=document.getElementById('skSandboxPhone')?.value||'';
            const model=document.getElementById('skSandboxModel')?.value||'';
            const n=document.getElementById('billCustName'); if(n&&name)n.value=name;
            const ph=document.getElementById('billCustPhone'); if(ph&&phone)ph.value=phone;
            const md=document.getElementById('billModel'); if(md&&model)md.value=model;
            window.updateBillPreview?.();
          }
        };
        if(go[action])go[action]();
      }catch(e){console.warn('Appearance sandbox action failed:',action,e);}
    }
    function skInitAppearanceSandbox(){
      let tab='home';
      try{tab=sessionStorage.getItem('sk_ui_sandbox_tab')||'home';}catch(e){}
      skAppearanceSandboxSet(tab);
    }
    window.skAppearanceSandboxSet=skAppearanceSandboxSet;
    window.skAppearanceSet=skAppearanceSet;
    window.skAppearanceSetCustomAccent=skAppearanceSetCustomAccent;
    window.skResetAppearanceStudio=skResetAppearanceStudio;
    window.skInitUIAppearanceStudio=skInitUIAppearanceStudio;

    function setTheme(theme, silent) {
      const allowedThemes = ['light','ocean','royal','sunset','emerald','rose','midnight','graphite','lime','dark','cyber','obsidian','aurora','crimson','mint','solar','nebula','forest','glacier','magenta','apple-light','apple-dark'];
      if (!allowedThemes.includes(theme)) theme = 'light';
      document.documentElement.setAttribute('data-theme', theme);
      const iconPack = THEME_ICON_PACK[theme] || 'classic';
      document.documentElement.setAttribute('data-icon-pack', iconPack);
      const pack = NAV_ICON_PACKS[iconPack];
      document.querySelectorAll('.bottom-nav .nav-item').forEach(nav => {
        const svg = nav.querySelector('svg');
        if (svg && pack[nav.id]) svg.innerHTML = pack[nav.id];
      });
      document.querySelectorAll('.theme-card-btn[data-theme-choice]').forEach(btn => {
        btn.classList.toggle('active', btn.getAttribute('data-theme-choice') === theme);
      });
      localStorage.setItem('sk_theme', theme);
      localStorage.setItem('sk_icon_pack', iconPack);
      skUpdateThemeChrome(theme);
      try { skAppearanceSyncFromLegacyTheme(theme); } catch (e) {}
      if(!silent) showToast("Theme applied: " + theme.toUpperCase());
    }

    function adjustThemeDepth(val) {
      const depthFactor = val / 100;
      document.documentElement.style.setProperty('--glass-shadow', `0 4px ${14 * depthFactor}px rgba(37, 99, 235, ${0.12 * depthFactor})`);
      const label = document.getElementById('depthValueLabel');
      if (label) label.innerText = val + '%';
      localStorage.setItem('sk_theme_depth', val);
    }

    function resetThemeToDefault() {
      if (window.skResetAppearanceStudio) { skResetAppearanceStudio(); return; }
      setTheme('light');
      localStorage.removeItem('sk_theme');
      localStorage.removeItem('sk_theme_depth');
      const slider = document.getElementById('themeDepthSlider');
      if (slider) slider.value = 100;
      adjustThemeDepth(100);
      showToast("Theme reset to Classic Light Default!");
    }

    function openItemEditor() {
      const category = currentFilter === 'combo' ? 'combo' : 'glass';
      const categoryField = document.getElementById('editItemCategory');
      if (categoryField) categoryField.value = category;
      const title = document.getElementById('itemModalTitle');
      if (title) title.textContent = category === 'combo' ? '📱 Add Touch Combo Item' : '🛡️ Add Tempered Glass Item';
      renderItemModalList(category);
      toggleModal('itemEditorModal', true);
    }

    function renderItemModalList(category) {
      const target = document.getElementById('itemModalListContent');
      if (!target) return;

      const items = inventory.filter(item => item && item.category === category);
      if (!items.length) {
        target.innerHTML = '<div style="padding:10px;border:1px dashed var(--card-border);border-radius:10px;color:var(--text-muted);font-size:.72rem;">No items added yet.</div>';
        return;
      }

      target.innerHTML = items.map(item => `
        <div style="padding:9px 10px;border:1px solid var(--card-border);border-radius:11px;background:var(--card-bg);margin-bottom:6px;">
          <div style="display:flex;justify-content:space-between;gap:14px;align-items:center;">
            <div style="font-weight:850;font-size:.78rem;color:var(--text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${item.title}</div>
            <div style="font-size:.68rem;font-weight:800;color:var(--primary);white-space:nowrap;">${item.stock} pcs</div>
          </div>
          <div style="font-size:.66rem;color:var(--text-muted);margin-top:3px;line-height:1.35;">${item.models.join(' • ')}</div>
        </div>
      `).join('');
    }

    function handleExcelFileUpload(input) {
      if (!input.files || !input.files[0]) return;
      const file = input.files[0];
      const reader = new FileReader();
      reader.onload = function (e) {
        try {
          const data = new Uint8Array(e.target.result);
          const workbook = XLSX.read(data, { type: 'array' });
          const firstSheetName = workbook.SheetNames[0];
          const worksheet = workbook.Sheets[firstSheetName];
          const rows = XLSX.utils.sheet_to_json(worksheet, { defval: '', raw: false });
          if (!rows.length) {
            showToast("Excel file is empty!");
            return;
          }

          let addedCount = 0;
          rows.forEach((row, index) => {
            const categoryRaw = String(row['Category'] || row['category'] || '').trim().toLowerCase();
            const category = categoryRaw === 'display' || categoryRaw === 'touch combo' || categoryRaw === 'combo' ? 'combo' :
              categoryRaw === 'tempered glass' || categoryRaw === 'glass' ? 'glass' : '';
            const title = String(row['Item Title'] || row['Title'] || row['item title'] || '').trim();
            const stockValue = parseInt(row['Initial Stock'] || row['Stock'] || row['initial stock'], 10);
            const modelsRaw = String(row['Compatible Models'] || row['Models'] || row['compatible models'] || '').trim();
            const models = modelsRaw.split(/,|\n|\|/).map(v => v.trim()).filter(Boolean);

            if (!category || !models.length) return;
            const finalTitle = title || models.slice(0, 4).join(' / ') + (models.length > 4 ? ' / ...' : '');
            const newItem = {
              id: `SK-EXC-${Date.now().toString().slice(-5)}_${index}`,
              title: finalTitle,
              category,
              subType: category === 'combo' ? 'combo' : '11d',
              spec: 'Universal',
              stock: Number.isFinite(stockValue) && stockValue >= 0 ? stockValue : 15,
              ordered: false,
              note: 'Imported via Excel Stock Format',
              models
            };
            inventory.unshift(newItem);
            addedCount++;
          });

          if (!addedCount) {
            showToast("No valid rows found. Use the Download Excel Format Demo.");
            return;
          }
          saveInventory();
          renderCards();
          renderItemModalList(document.getElementById('editItemCategory')?.value || 'glass');
          toggleModal('itemEditorModal', false);
          showToast(`Successfully imported ${addedCount} stock items from Excel!`);

        } catch (err) {
          showToast("Failed to parse Excel file. Use the Download Excel Format Demo.");
        }
      };
      reader.readAsArrayBuffer(file);
    }

    function downloadInventoryExcelTemplate() {
      try {
        if (!window.XLSX) { showToast("Excel reader is unavailable."); return; }
        const rows = [
          ['Tempered Glass Compatible Models', 'Display Compatible Models'],
          ['iPhone 16 | iPhone 17 | iPhone 18', 'Samsung A55 | Samsung A55 5G'],
          ['Redmi Note 13 | Redmi Note 14', 'iPhone 15 | iPhone 16']
        ];
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.aoa_to_sheet(rows);
        ws['!cols'] = [{wch:38},{wch:38}];
        XLSX.utils.book_append_sheet(wb, ws, 'Stock Format');

        // Use a direct Blob download so the demo works reliably on mobile and desktop browsers.
        const data = XLSX.write(wb, { bookType: 'xlsx', type: 'array' });
        const blob = new Blob([data], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'SK_Mobiles_Stock_Import_Format.xlsx';
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        showToast("Excel format demo downloaded.");
      } catch (e) {
        console.error('Excel format download failed:', e);
        showToast("Excel format download failed.");
      }
    }

    function saveManualInventoryItem() {
      let title = document.getElementById('editItemTitle').value.trim();
      const category = document.getElementById('editItemCategory').value;
      const stock = parseInt(document.getElementById('editItemStock').value) || 15;
      const modelsRaw = document.getElementById('editItemModels').value.trim();
      const models = modelsRaw.split(/,|\n|\|/).map(m => m.trim()).filter(Boolean);

      if (models.length === 0) {
        showToast("Models are required!");
        return;
      }

      if (!title) {
        let titleModels = models.slice(0, 4);
        title = titleModels.join(' / ');
        if (models.length > 4) title += ' / ...';
      }

      const newItem = {
        id: `SK-M-${Date.now().toString().slice(-4)}`,
        title,
        category,
        subType: category === 'combo' ? 'combo' : '11d',
        spec: 'Universal',
        stock,
        ordered: false,
        note: 'Manually Added Item',
        models
      };
      inventory.unshift(newItem);
      saveInventory();
      if (typeof window.skSaveCurrentInventoryExcel === 'function') window.skSaveCurrentInventoryExcel();
      renderCards();
      renderItemModalList(category);
      document.getElementById('itemEditorForm')?.reset();
      const editIdField = document.getElementById('editItemId');
      if (editIdField) editIdField.value = '';
      toggleModal('itemEditorModal', false);
      showToast("New item added successfully!");
    }

    function deleteInventoryItem(id) {
      if (!confirm("Are you sure you want to delete this inventory item?")) return;
      const trashItem = Array.isArray(inventory) ? inventory.find(i => String(i.id) === String(id)) : null;
      if (trashItem && typeof window.moveToTrash === 'function') window.moveToTrash(trashItem, 'inventory', trashItem.title || trashItem.id);
      inventory = inventory.filter(i => i.id !== id);
      saveInventory();
      renderCards();
      toggleModal('longPressMenuModal', false);
      showToast("Item deleted!");
    }

    // Direct inventory long-press selection logic for Tempered Glass and Touch Combo.
    // This is the single implementation used by both categories; no wrapper patch is used.
    let longPressTimer = null;
    let inventorySelectionTimer = null;
    let inventorySelectionMode = false;
    let inventorySelectedIds = new Set();
    let inventorySuppressClickUntil = 0;

    function isInventorySelectionCategory() {
      return currentFilter === 'glass' || currentFilter === 'combo';
    }

    function getInventoryCardId(card) {
      if (!card) return '';
      const onclick = card.getAttribute('onclick') || '';
      const match = onclick.match(/openModelsPopup\(['"]([^'"]+)['"]\)/);
      return match ? match[1] : '';
    }

    function clearInventorySelectionChecks() {
      document.querySelectorAll('#cardsContainer .sk-tempered-check-wrap').forEach(el => el.remove());
    }

    function addInventorySelectionChecks() {
      const container = document.getElementById('cardsContainer');
      if (!container || !inventorySelectionMode || !isInventorySelectionCategory()) return;
      clearInventorySelectionChecks();

      container.querySelectorAll('.glass-card').forEach(card => {
        const id = getInventoryCardId(card);
        if (!id) return;

        const wrap = document.createElement('label');
        wrap.className = 'sk-tempered-check-wrap';
        wrap.title = 'Select box';

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'sk-tempered-check';
        checkbox.checked = inventorySelectedIds.has(id);
        checkbox.dataset.id = id;

        checkbox.addEventListener('click', event => event.stopPropagation());
        checkbox.addEventListener('change', event => {
          event.stopPropagation();
          if (checkbox.checked) inventorySelectedIds.add(id);
          else inventorySelectedIds.delete(id);
          card.classList.toggle('sk-tempered-selected', checkbox.checked);
          updateInventorySelectAllLabel();
        });

        wrap.appendChild(checkbox);
        wrap.addEventListener('click', event => event.stopPropagation());
        card.appendChild(wrap);
        card.classList.toggle('sk-tempered-selected', inventorySelectedIds.has(id));
      });

      updateInventorySelectAllLabel();
    }

    function updateInventorySelectAllLabel() {
      const button = document.getElementById('skTemperedSelectAllBtn');
      const container = document.getElementById('cardsContainer');
      if (!button || !container) return;
      const ids = Array.from(container.querySelectorAll('.glass-card'))
        .map(getInventoryCardId)
        .filter(Boolean);
      button.textContent =
        ids.length > 0 && ids.every(id => inventorySelectedIds.has(id))
          ? '☑️ Deselect All'
          : '☑️ Select All';
    }

    function placeInventorySelectionBar() {
      const container = document.getElementById('cardsContainer');
      const bar = document.getElementById('skTemperedSelectBar');
      if (!container || !bar || !inventorySelectionMode || !isInventorySelectionCategory()) return;

      const notice = container.querySelector(':scope > .active-category-notice');
      if (notice) notice.insertAdjacentElement('afterend', bar);
      else container.insertBefore(bar, container.firstElementChild);
      bar.classList.add('sk-active');
      bar.style.display = 'flex';
      container.classList.add('sk-tempered-selection-mode');
    }

    function enterInventorySelectionMode() {
      if (!isInventorySelectionCategory()) return;

      inventorySelectionMode = true;
      inventorySelectedIds.clear();
      inventorySuppressClickUntil = Date.now() + 1200;

      const container = document.getElementById('cardsContainer');
      if (container) container.classList.add('sk-tempered-selection-mode');

      const bar = document.getElementById('skTemperedSelectBar');
      if (bar) bar.classList.add('sk-active');

      toggleModal('longPressMenuModal', false);
      placeInventorySelectionBar();
      addInventorySelectionChecks();

      if (navigator.vibrate) navigator.vibrate(70);
    }

    window.skCancelTemperedSelection = function() {
      inventorySelectionMode = false;
      inventorySelectedIds.clear();
      clearTimeout(inventorySelectionTimer);
      clearInventorySelectionChecks();

      const container = document.getElementById('cardsContainer');
      const bar = document.getElementById('skTemperedSelectBar');

      if (container) {
        container.classList.remove('sk-tempered-selection-mode');
        container.querySelectorAll('.glass-card.sk-tempered-selected')
          .forEach(card => card.classList.remove('sk-tempered-selected'));
      }

      if (bar) {
        bar.classList.remove('sk-active');
        bar.style.display = 'none';
        if (bar.parentElement === container) document.body.appendChild(bar);
      }

      const selectAll = document.getElementById('skTemperedSelectAllBtn');
      if (selectAll) selectAll.textContent = '☑️ Select All';
    };

    window.skToggleSelectAllTempered = function() {
      if (!inventorySelectionMode || !isInventorySelectionCategory()) return;

      const container = document.getElementById('cardsContainer');
      if (!container) return;

      const ids = Array.from(container.querySelectorAll('.glass-card'))
        .map(getInventoryCardId)
        .filter(Boolean);

      const allSelected = ids.length > 0 && ids.every(id => inventorySelectedIds.has(id));
      if (allSelected) inventorySelectedIds.clear();
      else ids.forEach(id => inventorySelectedIds.add(id));

      addInventorySelectionChecks();
    };

    window.skDeleteSelectedTempered = function() {
      const ids = Array.from(inventorySelectedIds);
      if (!ids.length) {
        showToast('Select at least one box!');
        return;
      }

      const trashItems = inventory.filter(item => ids.includes(item.id));
      if (trashItems.length && typeof window.moveToTrash === 'function') window.moveToTrash(trashItems, 'inventory-batch', `${trashItems.length} inventory item(s)`);
      inventory = inventory.filter(item => !ids.includes(item.id));
      saveInventory();
      window.skCancelTemperedSelection();
      renderCards();
      showToast(ids.length === 1 ? 'Box deleted!' : `${ids.length} boxes deleted!`);
    };

    function syncInventorySelectionUI() {
      if (!isInventorySelectionCategory()) {
        if (inventorySelectionMode) window.skCancelTemperedSelection();
        return;
      }
      if (inventorySelectionMode) {
        placeInventorySelectionBar();
        addInventorySelectionChecks();
      }
    }

    function handleCardTouchStart(id) {
      clearTimeout(longPressTimer);
      clearTimeout(inventorySelectionTimer);

      if (isInventorySelectionCategory()) {
        inventorySelectionTimer = setTimeout(() => {
          enterInventorySelectionMode();
        }, 600);
        return;
      }

      longPressTimer = setTimeout(() => {
        if (navigator.vibrate) navigator.vibrate(80);
        document.getElementById('selectedContextId').value = id;
        toggleModal('longPressMenuModal', true);
      }, 600);
    }

    function handleCardTouchEnd() {
      clearTimeout(longPressTimer);
      clearTimeout(inventorySelectionTimer);
    }

    // Android/WebView long-press fallback: use pointer events + contextmenu so
    // selection works reliably even when touchend/click timing differs by device.
    let skPointerLongPressTimer = null;
    let skPointerLongPressCard = null;
    document.addEventListener('pointerdown', function(event){
      if (!isInventorySelectionCategory()) return;
      const card = event.target.closest && event.target.closest('#cardsContainer .glass-card');
      if (!card) return;
      if (event.pointerType === 'mouse' && event.button !== 0) return;
      clearTimeout(skPointerLongPressTimer);
      skPointerLongPressCard = card;
      skPointerLongPressTimer = setTimeout(function(){
        const id = getInventoryCardId(card);
        if (id) {
          enterInventorySelectionMode();
          inventorySuppressClickUntil = Date.now() + 1200;
        }
      }, 550);
    }, {passive:true});
    ['pointerup','pointercancel','pointerleave'].forEach(function(type){
      document.addEventListener(type, function(event){
        clearTimeout(skPointerLongPressTimer);
        skPointerLongPressCard = null;
      }, {passive:true});
    });
    document.addEventListener('contextmenu', function(event){
      const card = event.target.closest && event.target.closest('#cardsContainer .glass-card');
      if (!card || !isInventorySelectionCategory()) return;
      event.preventDefault();
      event.stopPropagation();
      enterInventorySelectionMode();
    }, true);

    document.addEventListener('click', function(event) {
      const card = event.target.closest && event.target.closest('#cardsContainer .glass-card');

      if (Date.now() < inventorySuppressClickUntil && card) {
        event.preventDefault();
        event.stopImmediatePropagation();
        inventorySuppressClickUntil = 0;
        return;
      }

      if (!inventorySelectionMode || !card) return;
      if (event.target.closest && event.target.closest('.sk-tempered-check-wrap')) return;

      event.preventDefault();
      event.stopImmediatePropagation();

      const id = getInventoryCardId(card);
      if (!id) return;

      if (inventorySelectedIds.has(id)) inventorySelectedIds.delete(id);
      else inventorySelectedIds.add(id);

      const checkbox = card.querySelector('.sk-tempered-check');
      if (checkbox) checkbox.checked = inventorySelectedIds.has(id);
      card.classList.toggle('sk-tempered-selected', inventorySelectedIds.has(id));
      updateInventorySelectAllLabel();
    }, true);

    function triggerEditFromContext() {
      const id = document.getElementById('selectedContextId').value;
      toggleModal('longPressMenuModal', false);
      const item = inventory.find(i => i.id === id);
      if (item) {
        const newStock = prompt("Enter new stock count:", item.stock);
        if (newStock !== null) {
          item.stock = Math.max(0, parseInt(newStock) || 0);
          saveInventory();
          renderCards();
          showToast("Stock updated!");
        }
      }
    }

    function triggerDeleteFromContext() {
      const id = document.getElementById('selectedContextId').value;
      toggleModal('longPressMenuModal', false);
      deleteInventoryItem(id);
    }

    function saveDraft() {
      const draft = {
        custName: document.getElementById('billCustName').value,
        phone: document.getElementById('billCustPhone').value,
        address: document.getElementById('billCustAddress').value,
        brand: document.getElementById('billBrand').value,
        model: document.getElementById('billModel').value,
        ram: document.getElementById('billRam').value,
        storage: document.getElementById('billStorage').value,
        color: document.getElementById('billColor').value,
        package: document.getElementById('billPackage').value,
        imei1: document.getElementById('billImei1').value,
        imei2: document.getElementById('billImei2').value,
        payMode: currentPayMode,
        mobileType: currentMobileType,
        price: document.getElementById('billTotalPrice').value,
        advance: document.getElementById('billAdvance').value,
        emiMonths: document.getElementById('billEmiMonths').value,
        emiInterest: document.getElementById('billEmiInterest').value,
        emiStartDate: document.getElementById('billEmiStartDate').value,
        creditDate: document.getElementById('billCreditDate').value
      };
      localStorage.setItem('sk_bill_draft', JSON.stringify(draft));
    }

    function restoreDraft() {
      const draftStr = localStorage.getItem('sk_bill_draft');
      if (!draftStr) return;
      try {
        const d = JSON.parse(draftStr);
        document.getElementById('billCustName').value = d.custName || '';
        document.getElementById('billCustPhone').value = d.phone || '';
        document.getElementById('billCustAddress').value = d.address || '';
        document.getElementById('billBrand').value = d.brand || '';
        document.getElementById('billModel').value = d.model || '';
        document.getElementById('billRam').value = d.ram || '';
        document.getElementById('billStorage').value = d.storage || '';
        document.getElementById('billColor').value = d.color || '';
        document.getElementById('billPackage').value = d.package || 'Full Kit (Box + Charger + Bill)';
        document.getElementById('billImei1').value = d.imei1 || '';
        document.getElementById('billImei2').value = d.imei2 || '';
        document.getElementById('billTotalPrice').value = d.price || '';
        document.getElementById('billAdvance').value = d.advance || '0';
        document.getElementById('billEmiMonths').value = d.emiMonths || '3';
        document.getElementById('billEmiInterest').value = d.emiInterest || '0';
        document.getElementById('billEmiStartDate').value = d.emiStartDate || '';
        document.getElementById('billEmiStartDate').dataset.autoDefault = d.emiStartDate ? '0' : '1';
        document.getElementById('billCreditDate').value = d.creditDate || '';

        if (d.mobileType) selectMobileType(d.mobileType);
        if (d.payMode) selectPayMode(d.payMode);
        calculateBillMath();
      } catch (e) {}
    }

    function clearDraft() {
      localStorage.removeItem('sk_bill_draft');
    }

    function parseSmartDate(str) {
      if (!str) return '';
      let clean = str.trim().replace(/[-.]/g, '/');
      let d, m, y;

      if (clean.includes('/')) {
        let parts = clean.split(/[-\/]/);
        if (parts.length === 3) {
          d = parseInt(parts[0], 10);
          m = parseInt(parts[1], 10);
          y = parseInt(parts[2], 10);
        }
      } else {
        let digits = clean.replace(/\D/g, '');
        if (digits.length === 4) {
          d = parseInt(digits.slice(0, 1), 10);
          m = parseInt(digits.slice(1, 2), 10);
          y = parseInt(digits.slice(2, 4), 10);
        } else if (digits.length === 5) {
          d = parseInt(digits.slice(0, 2), 10);
          m = parseInt(digits.slice(2, 3), 10);
          y = parseInt(digits.slice(3, 5), 10);
        } else if (digits.length === 6) {
          d = parseInt(digits.slice(0, 2), 10);
          m = parseInt(digits.slice(2, 4), 10);
          y = parseInt(digits.slice(4, 6), 10);
        } else if (digits.length === 8) {
          d = parseInt(digits.slice(0, 2), 10);
          m = parseInt(digits.slice(2, 4), 10);
          y = parseInt(digits.slice(4, 8), 10);
        }
      }

      if (!d || !m || !y) return str;
      if (y < 100) y = 2000 + y;

      return `${String(d).padStart(2, '0')}/${String(m).padStart(2, '0')}/${y}`;
    }

    function handleSmartDateInput(input) {
      const formatted = parseSmartDate(input.value);
      if (formatted) input.value = formatted;
    }

    function skDmyToISO(value){
      const s=String(value||'').trim();
      if(/^\d{4}-\d{1,2}-\d{1,2}$/.test(s)){const p=s.split('-');return p[0]+'-'+String(Number(p[1])).padStart(2,'0')+'-'+String(Number(p[2])).padStart(2,'0');}
      const m=s.match(/^(\d{1,2})[\/.-](\d{1,2})[\/.-](\d{2,4})$/);
      if(!m)return '';
      let y=Number(m[3]); if(y<100)y+=2000; const d=Number(m[1]),mo=Number(m[2]);
      if(d<1||d>31||mo<1||mo>12||y<1900)return '';
      return y+'-'+String(mo).padStart(2,'0')+'-'+String(d).padStart(2,'0');
    }
    function skISOToDmy(value){
      const s=String(value||'').trim();
      let m=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
      if(m)return String(Number(m[3])).padStart(2,'0')+'/'+String(Number(m[2])).padStart(2,'0')+'/'+m[1];
      return parseSmartDate(s);
    }
    function skNormalizeDmyInput(input){
      if(!input)return;
      const iso=skDmyToISO(input.value);
      if(iso) input.value=skISOToDmy(iso);
    }
    function skInitDmyDateInputs(root){
      (root||document).querySelectorAll('input[data-dmy-date]').forEach(function(input){
        if(input.dataset.dmyBound==='1')return;
        input.dataset.dmyBound='1'; input.type='text'; input.inputMode='numeric'; input.autocomplete='off'; input.placeholder='DD/MM/YYYY';
        skNormalizeDmyInput(input);
        input.addEventListener('input',function(){
          const digits=this.value.replace(/\D/g,'').slice(0,8);
          if(digits.length<=2)this.value=digits;
          else if(digits.length<=4)this.value=digits.slice(0,2)+'/'+digits.slice(2);
          else this.value=digits.slice(0,2)+'/'+digits.slice(2,4)+'/'+digits.slice(4);
        });
        input.addEventListener('blur',function(){skNormalizeDmyInput(this)});
      });
    }
    window.skDmyToISO=skDmyToISO; window.skISOToDmy=skISOToDmy; window.skInitDmyDateInputs=skInitDmyDateInputs;

    function openModelsPopup(id) {
      const item = inventory.find(i => i.id === id);
      if (!item) return;

      document.getElementById('modalModelTitle').innerText = item.title;
      document.getElementById('modalModelSubtitle').innerText = `${item.models.length} Compatible Models (Stock: ${item.stock} pcs):`;
      
      const container = document.getElementById('modalModelsContainer');
      container.innerHTML = item.models.map(m => `<span class="model-chip" style="font-size:0.75rem; padding:5px 10px;">${m}</span>`).join('');
      
      toggleModal('modelsModal', true);
    }

    /* UNIVERSAL DRAG AND DROP HANDLERS FOR ALL BOXES & CARDS */
    let draggedElement = null;

    function handleCardDragStart(e) {
      draggedElement = this;
      this.classList.add('dragging');
      e.dataTransfer.effectAllowed = 'move';
    }

    function handleCardDragOver(e) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      const targetCard = e.currentTarget;
      if (targetCard && targetCard !== draggedElement && targetCard.parentNode === draggedElement.parentNode) {
        targetCard.classList.add('drag-over');
      }
    }

    function handleCardDragLeave(e) {
      e.currentTarget.classList.remove('drag-over');
    }

    function handleCardDrop(e) {
      e.preventDefault();
      e.stopPropagation();
      const targetCard = e.currentTarget;
      targetCard.classList.remove('drag-over');
      if (draggedElement && targetCard && draggedElement !== targetCard && targetCard.parentNode === draggedElement.parentNode) {
        const parent = targetCard.parentNode;
        const allCards = Array.from(parent.querySelectorAll('.draggable-card'));
        const draggedIndex = allCards.indexOf(draggedElement);
        const targetIndex = allCards.indexOf(targetCard);

        if (draggedIndex < targetIndex) {
          parent.insertBefore(draggedElement, targetCard.nextSibling);
        } else {
          parent.insertBefore(draggedElement, targetCard);
        }

        saveUniversalBoxOrder(parent.id);
        showToast("Position updated!");
      }
    }

    function handleCardDragEnd(e) {
      this.classList.remove('dragging');
      document.querySelectorAll('.draggable-card').forEach(c => c.classList.remove('drag-over'));
      draggedElement = null;
    }

    function saveUniversalBoxOrder(containerId) {
      const container = document.getElementById(containerId);
      if (!container) return;
      const ids = Array.from(container.querySelectorAll('.draggable-card')).map(card => card.dataset.cardId);
      localStorage.setItem(`sk_order_${containerId}`, JSON.stringify(ids));
    }

